using System.Windows;
using DesktopOrganizer.Core;
using DesktopOrganizer.Services.Abstractions;
using DesktopOrganizer.Services.Abstractions.Storage;
using DesktopOrganizer.Tests.Helpers;
using DesktopOrganizer.UI.Services;
using DesktopOrganizer.UI.ViewModels;
using Moq;

namespace DesktopOrganizer.Tests.Unit.ViewModels;

/// <summary>
/// Unit tests for <see cref="LayoutSnapshotsViewModel"/> — the settings-window redesign's WP-C behaviour
/// fixes: capturing a snapshot now prompts for its name via <see cref="IInputDialogService"/> instead of
/// silently using an auto-generated one, and deleting a snapshot is gated behind
/// <see cref="IConfirmationService"/> (previously only claimed by this type's own constructor XML-doc,
/// not actually implemented — see <c>docs/prompts/settings-window-redesign.md</c> D-10/Backup row).
/// </summary>
[Trait(UnitTests, "DesktopOrganizer.UI")]
public class LayoutSnapshotsViewModelTests
{
    private readonly Mock<ILayoutSnapshotService> _serviceMock = new();
    private readonly Mock<IConfirmationService> _confirmationMock = new();
    private readonly Mock<IInputDialogService> _inputDialogMock = new();
    private readonly Mock<IApplicationStateStore> _stateStoreMock = new();

    /// <summary>
    /// Initializes a new instance of the <see cref="LayoutSnapshotsViewModelTests"/> class.
    /// </summary>
    public LayoutSnapshotsViewModelTests()
    {
        _serviceMock.Setup(s => s.Snapshots).Returns([]);
        _stateStoreMock.SetupGet(s => s.IsWritable).Returns(true);
    }

    /// <summary>
    /// Verifies that <see cref="LayoutSnapshotsViewModel.CaptureSnapshotCommand"/> prompts for a name with
    /// an auto-generated default of the previously-used <c>"Layout dd.MM HH:mm"</c> shape, and — when the
    /// user accepts the prompt — captures the snapshot under the entered (not the default) name.
    /// </summary>
    [Fact]
    public void CaptureSnapshot_PromptsWithAutoGeneratedDefault_AndCapturesUnderEnteredName()
    {
        string? promptedDefault = null;
        _inputDialogMock
            .Setup(d => d.PromptText(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<string>()))
            .Callback<string, string, string>((_, _, defaultValue) => promptedDefault = defaultValue)
            .Returns("My custom name");
        var sut = BuildSut();

        sut.CaptureSnapshotCommand.Execute(null);

        Assert.NotNull(promptedDefault);
        Assert.Matches(@"^Layout \d{2}\.\d{2} \d{2}:\d{2}$", promptedDefault!);
        _serviceMock.Verify(s => s.Capture("My custom name"), Times.Once);
    }

    /// <summary>
    /// Verifies that cancelling the name prompt (a <see langword="null"/> result) captures nothing.
    /// </summary>
    [Fact]
    public void CaptureSnapshot_PromptCancelled_CapturesNothing()
    {
        _inputDialogMock
            .Setup(d => d.PromptText(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<string>()))
            .Returns((string?)null);
        var sut = BuildSut();

        sut.CaptureSnapshotCommand.Execute(null);

        _serviceMock.Verify(s => s.Capture(It.IsAny<string>()), Times.Never);
    }

    /// <summary>
    /// Verifies that a blank or whitespace-only name from the prompt captures nothing, the same as an
    /// outright cancel — defense in depth matching <see cref="LayoutSnapshotsViewModel.RestoreSnapshotCommand"/>/
    /// <see cref="LayoutSnapshotsViewModel.DeleteSnapshotCommand"/>'s own <c>IsNullOrWhiteSpace</c>
    /// guards, even though the real <c>InputDialog</c>'s OK button is already disabled for blank input.
    /// </summary>
    [Fact]
    public void CaptureSnapshot_BlankOrWhitespaceName_CapturesNothing()
    {
        _inputDialogMock
            .Setup(d => d.PromptText(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<string>()))
            .Returns("   ");
        var sut = BuildSut();

        sut.CaptureSnapshotCommand.Execute(null);

        _serviceMock.Verify(s => s.Capture(It.IsAny<string>()), Times.Never);
    }

    /// <summary>
    /// Verifies that <see cref="LayoutSnapshotsViewModel.DeleteSnapshotCommand"/> asks for confirmation,
    /// naming the snapshot in the message, before deleting it — matching the constructor's XML-doc
    /// contract, which previously wasn't honored by the implementation.
    /// </summary>
    [Fact]
    public void DeleteSnapshot_AsksConfirmation_NamingTheSnapshot_ThenDeletes()
    {
        var snapshot = new LayoutSnapshot { Id = "abc", Name = "Morning layout" };
        _serviceMock.Setup(s => s.Snapshots).Returns([snapshot]);
        string? confirmMessage = null;
        MessageBoxImage? confirmIcon = null;
        _confirmationMock
            .Setup(c => c.Confirm(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<MessageBoxImage>()))
            .Callback<string, string, MessageBoxImage>((message, _, icon) =>
            {
                confirmMessage = message;
                confirmIcon = icon;
            })
            .Returns(true);
        var sut = BuildSut();

        sut.DeleteSnapshotCommand.Execute(snapshot.Id);

        Assert.NotNull(confirmMessage);
        Assert.Contains("Morning layout", confirmMessage);
        Assert.Equal(MessageBoxImage.Warning, confirmIcon);
        _serviceMock.Verify(s => s.Delete(snapshot.Id), Times.Once);
    }

    /// <summary>
    /// Verifies that declining the delete confirmation leaves the snapshot untouched.
    /// </summary>
    [Fact]
    public void DeleteSnapshot_ConfirmationDeclined_DoesNotDelete()
    {
        var snapshot = new LayoutSnapshot { Id = "abc", Name = "Morning layout" };
        _serviceMock.Setup(s => s.Snapshots).Returns([snapshot]);
        _confirmationMock
            .Setup(c => c.Confirm(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<MessageBoxImage>()))
            .Returns(false);
        var sut = BuildSut();

        sut.DeleteSnapshotCommand.Execute(snapshot.Id);

        _serviceMock.Verify(s => s.Delete(It.IsAny<string>()), Times.Never);
    }

    /// <summary>
    /// Verifies that <see cref="LayoutSnapshotsViewModel.RestoreSnapshotCommand"/> still gates on
    /// confirmation exactly as before this fix (no regression from the delete-confirmation addition).
    /// </summary>
    [Fact]
    public void RestoreSnapshot_ConfirmationAccepted_Restores()
    {
        _confirmationMock
            .Setup(c => c.Confirm(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<MessageBoxImage>()))
            .Returns(true);
        var sut = BuildSut();

        sut.RestoreSnapshotCommand.Execute("snap-1");

        _serviceMock.Verify(s => s.Restore("snap-1"), Times.Once);
    }

    /// <summary>
    /// F6: the restore confirmation names both consequences - panels outside the snapshot close, their files
    /// return to the original location - as two paragraphs.
    /// </summary>
    [Fact]
    public void RestoreSnapshot_Confirmation_TellsPanelsCloseAndFilesReturn()
    {
        string? shown = null;
        _confirmationMock
            .Setup(c => c.Confirm(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<MessageBoxImage>()))
            .Callback<string, string, MessageBoxImage>((message, _, _) => shown = message)
            .Returns(false);
        var sut = BuildSut();

        sut.RestoreSnapshotCommand.Execute("snap-1");

        Assert.NotNull(shown);
        Assert.Contains("closed", shown!, StringComparison.Ordinal);
        Assert.Contains("original location", shown!, StringComparison.Ordinal);
        Assert.Contains("\n\n", shown!, StringComparison.Ordinal);
    }

    /// <summary>
    /// M3: in a read-only session a restore moves no file, so the confirmation must not promise that the files
    /// return to their original location - only the panels paragraph is shown.
    /// </summary>
    [Fact]
    public void RestoreSnapshot_ReadOnlySession_Confirmation_DoesNotPromiseFileReturn()
    {
        string? shown = null;
        _stateStoreMock.SetupGet(s => s.IsWritable).Returns(false);
        _confirmationMock
            .Setup(c => c.Confirm(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<MessageBoxImage>()))
            .Callback<string, string, MessageBoxImage>((message, _, _) => shown = message)
            .Returns(false);
        var sut = BuildSut();

        sut.RestoreSnapshotCommand.Execute("snap-1");

        Assert.NotNull(shown);
        Assert.Contains("closed", shown!, StringComparison.Ordinal);
        Assert.DoesNotContain("original location", shown!, StringComparison.Ordinal);
        Assert.DoesNotContain("\n\n", shown!, StringComparison.Ordinal);
    }

    /// <summary>
    /// Verifies that declining the restore confirmation leaves the current layout untouched — the same
    /// regression guard as <see cref="DeleteSnapshot_ConfirmationDeclined_DoesNotDelete"/>, for the
    /// sibling command.
    /// </summary>
    [Fact]
    public void RestoreSnapshot_ConfirmationDeclined_DoesNotRestore()
    {
        _confirmationMock
            .Setup(c => c.Confirm(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<MessageBoxImage>()))
            .Returns(false);
        var sut = BuildSut();

        sut.RestoreSnapshotCommand.Execute("snap-1");

        _serviceMock.Verify(s => s.Restore(It.IsAny<string>()), Times.Never);
    }

    // ── Snapshot_DefaultName_Format (docs/PLANS/localization.md D-5): resolved at creation time in the
    // current UI language ─────────────────────────────────────────────────────────────────────────────

    /// <summary>
    /// Verifies that the auto-generated default snapshot name uses the English
    /// <c>Snapshot_DefaultName_Format</c> ("Layout dd.MM HH:mm") when the UI language is English.
    /// </summary>
    [Fact]
    public void CaptureSnapshot_DefaultName_English()
    {
        string? promptedDefault = null;
        _inputDialogMock
            .Setup(d => d.PromptText(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<string>()))
            .Callback<string, string, string>((_, _, defaultValue) => promptedDefault = defaultValue)
            .Returns((string?)null);
        var sut = BuildSut(TestLocalization.English);

        sut.CaptureSnapshotCommand.Execute(null);

        Assert.NotNull(promptedDefault);
        Assert.Matches(@"^Layout \d{2}\.\d{2} \d{2}:\d{2}$", promptedDefault!);
    }

    /// <summary>
    /// Verifies that the auto-generated default snapshot name uses the Russian
    /// <c>Snapshot_DefaultName_Format</c> ("Расположение dd.MM HH:mm") when the UI language is Russian.
    /// </summary>
    [Fact]
    public void CaptureSnapshot_DefaultName_Russian()
    {
        string? promptedDefault = null;
        _inputDialogMock
            .Setup(d => d.PromptText(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<string>()))
            .Callback<string, string, string>((_, _, defaultValue) => promptedDefault = defaultValue)
            .Returns((string?)null);
        var sut = BuildSut(TestLocalization.Russian);

        sut.CaptureSnapshotCommand.Execute(null);

        Assert.NotNull(promptedDefault);
        Assert.Matches(@"^Расположение \d{2}\.\d{2} \d{2}:\d{2}$", promptedDefault!);
    }

    private LayoutSnapshotsViewModel BuildSut(ILocalizationService? localization = null)
        => new(
            _serviceMock.Object,
            _confirmationMock.Object,
            _inputDialogMock.Object,
            localization ?? TestLocalization.English,
            _stateStoreMock.Object);
}
